// POST /api/bookmarks
router.post('/bookmarks', async (req, res, next) => {
  try {
    const { bookmark, warnings } = await service.createBookmark(req.body || {});
    const body = { bookmark };
    if (warnings.length) body.warnings = warnings;
    res.status(201).json(body);
  } catch (err) {
    next(err);
  }
});

