  try {
    await api(`/api/bookmarks/${id}`, {
      method: 'PUT',
      body: JSON.stringify({
        title,
        note: els.editNote.value,
        tags: parseTags(els.editTags.value),
      }),
    });
    els.dialog.close();
    await refresh();
  } catch (err) {
    setMessage(els.editMessage, err.message, 'error');
  }
});

